from pathlib import Path
import re, collections
seq = "".join(l.strip() for l in Path("region.fasta").read_text().splitlines() if not l.startswith(">")).upper()

print("== homopolymers (runs of >=5) ==")
for m in re.finditer(r"(.)\1{4,}", seq):
    print(f"  {m.group(0)[0]} x{len(m.group(0))} at {m.start()+1}")

print("\n== dinucleotide runs >=5 units ==")
for m in re.finditer(r"([ACGT][ACGT])\1{4,}", seq):
    print(f"  {m.group(0)} ({len(m.group(0))//2}x) at {m.start()+1}")

print("\n== trinucleotide/tetranucleotide runs >=4 units ==")
for m in re.finditer(r"([ACGT]{3,4})\1{3,}", seq):
    print(f"  {m.group(0)} ({len(m.group(0))//len(m.group(1))}x) at {m.start()+1}")

print("\n== restriction palindromes ==")
for p in ["GAATTC","CTGCAG","GGATCC","AAGCTT","GCGC","CCGG","AGCT","TCGA","GATC","CTAG","ACGT","TGCA","CATG","GTAC"]:
    n = len(re.findall("(?="+p+")", seq))
    if n: print(f"  {p} x {n}")

